// src/lib/mcp/tools/list-projects.ts
import { defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@0.25.1";
import { z } from "npm:zod@^3.25.76";
var list_projects_default = defineTool2({
  name: "list_projects",
  title: "Elenca i progetti",
  description: "Elenca i progetti/case study pubblici di GenGinering Solutions. Opzionalmente filtra per categoria o per tecnologia (tag).",
  inputSchema: {
    category: z.string().optional().describe("Categoria: Automazione Hardware, Automazione Software o Wireless Planning."),
    tag: z.string().optional().describe("Tecnologia da cercare nei tag, es. 'WinCC SCADA'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ category, tag }) => {
    const items = projects.filter(
      (p) => (!category || p.category.toLowerCase() === category.toLowerCase()) && (!tag || p.tags.some((t) => t.toLowerCase().includes(tag.toLowerCase())))
    );
    return {
      content: [{ type: "text", text: JSON.stringify(items, null, 2) }],
      structuredContent: { projects: items }
    };
  }
});

